# ABOUTME: Runs every eval with the deterministic stubs and writes a single Markdown report.
# ABOUTME: Regenerate the checked-in report with `python -m evals.run_all`.
from __future__ import annotations

import asyncio
from pathlib import Path

from . import (
    eval_angle_quality,
    eval_classification,
    eval_draft_gate,
    eval_inbound,
    eval_optout,
)

_HEADER = (
    "# Eval reports\n\n"
    "Generated by `python -m evals.run_all` with the deterministic stub model and "
    "stub judge, so these numbers are reproducible in CI without an API key. The "
    "model-driven evals also run against a real model via their `--live` flag.\n"
)


def build_report() -> str:
    """Run all evals and return their reports joined into one document."""
    sections = [
        eval_classification.to_markdown(eval_classification.run()),
        eval_optout.to_markdown(eval_optout.run()),
        eval_draft_gate.to_markdown(eval_draft_gate.run()),
        eval_angle_quality.to_markdown(eval_angle_quality.run()),
        eval_inbound.to_markdown(asyncio.run(eval_inbound.run())),
    ]
    return _HEADER + "\n---\n\n" + "\n---\n\n".join(s.strip() + "\n" for s in sections)


def main() -> None:
    report = build_report()
    out_path = Path(__file__).parent / "reports" / "EVAL_REPORTS.md"
    out_path.parent.mkdir(exist_ok=True)
    out_path.write_text(report, encoding="utf-8")
    print(f"wrote {out_path}")
    print(report)


if __name__ == "__main__":
    main()
